use super::*;
use serde_json::{Value, json};

fn post() -> ResourceIr {
    crate::resource::load_resource(
        std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("../../catalog/resources/post.toml"),
    )
    .unwrap()
}

fn comment_content(resource: &ResourceIr, vue: bool) -> String {
    if vue {
        format!(
            "<!-- @generated by RyFrame {} | resource: {} | source: {} -->\n<!-- 请勿手工修改；修改资源清单后重新生成。 -->\n<!-- 测试占位 -->\n",
            crate::GENERATOR_VERSION,
            resource.name,
            resource.source_path,
        )
    } else {
        format!(
            "// @generated by RyFrame {}\n// resource: {}\n// source: {}\n// 请勿手工修改；修改资源清单后重新生成。\n\n// 测试占位\n",
            crate::GENERATOR_VERSION,
            resource.name,
            resource.source_path,
        )
    }
}

fn resource_asset(resource: &ResourceIr, file: &str) -> Value {
    json!({
        "resource": resource.name,
        "root": "frontend",
        "path": format!("src/generated/resources/{}/{file}", resource.name),
        "content": comment_content(resource, file == "page.vue"),
    })
}

fn catalog_asset() -> Value {
    json!({
        "resource": "__catalog__",
        "root": "frontend",
        "path": "src/generated/resources/index.ts",
        "content": format!(
            "// @generated by RyFrame {}\n// 请勿手工修改；修改资源清单后重新生成。\n\n// 测试占位\n",
            crate::GENERATOR_VERSION,
        ),
    })
}

fn output(resources: &[ResourceIr], aggregate: bool) -> Value {
    let mut assets = Vec::new();
    for resource in resources {
        for file in [
            "api.ts",
            "page.vue",
            "registration.ts",
            "index.ts",
            "fields.ts",
        ] {
            assets.push(resource_asset(resource, file));
        }
    }
    if aggregate {
        assets.push(catalog_asset());
    }
    json!({
        "format_version": 1,
        "generator_version": crate::GENERATOR_VERSION,
        "assets": assets,
    })
}

fn decode(value: &Value, resources: &[ResourceIr], aggregate: bool) -> Vec<GeneratedAsset> {
    decode_assets(&serde_json::to_vec(value).unwrap(), resources, aggregate).unwrap()
}

fn reject_bytes(source: &[u8], resources: &[ResourceIr], aggregate: bool, message: &str) {
    let error = decode_assets(source, resources, aggregate).unwrap_err();
    assert!(error.message.contains(message), "{error}");
    assert!(!error.suggestion.is_empty());
    assert!(error.to_string().contains("修复建议"));
    assert!(!error.to_string().contains("秘密占位"));
}

fn reject(value: &Value, resources: &[ResourceIr], aggregate: bool, message: &str) {
    reject_bytes(
        &serde_json::to_vec(value).unwrap(),
        resources,
        aggregate,
        message,
    );
}

#[test]
fn accepts_complete_assets_and_sorts_recursive_modules() {
    let mut resources = vec![post(), post()];
    resources[1].name = "alpha_2".into();
    let mut value = output(&resources, true);
    let assets = value["assets"].as_array_mut().unwrap();
    for file in [
        "columns/part-0.ts",
        "columns/group-1-24.ts",
        "model/create/2/part-99.ts",
        "snake_case/7.ts",
    ] {
        assets.push(resource_asset(&resources[0], file));
    }
    assets.reverse();
    let expected_content = assets
        .iter()
        .map(|asset| {
            (
                asset["path"].as_str().unwrap().to_owned(),
                asset["content"].as_str().unwrap().to_owned(),
            )
        })
        .collect::<BTreeMap<_, _>>();
    let decoded = decode(&value, &resources, true);
    assert_eq!(decoded.len(), 15);
    assert!(decoded.windows(2).all(|pair| pair[0].path < pair[1].path));
    for asset in decoded {
        assert_eq!(asset.root, AssetRoot::Frontend);
        assert_eq!(asset.content, expected_content[asset.path.as_str()]);
    }
}

#[test]
fn accepts_empty_batches_and_requested_empty_catalog() {
    assert!(decode(&output(&[], false), &[], false).is_empty());
    let assets = decode(&output(&[], true), &[], true);
    assert_eq!(assets.len(), 1);
    assert_eq!(assets[0].resource, "__catalog__");
    assert_eq!(assets[0].path, "src/generated/resources/index.ts");
}

#[test]
fn rejects_each_missing_required_asset() {
    let resources = [post()];
    for index in 0..5 {
        let mut value = output(&resources, false);
        value["assets"].as_array_mut().unwrap().remove(index);
        reject(&value, &resources, false, "缺少资源必需资产");
    }
}

#[test]
fn rejects_missing_or_unrequested_catalog() {
    reject(&output(&[], false), &[], true, "缺少唯一聚合资产");
    reject(&output(&[], true), &[], false, "聚合资产未获请求");
    let resources = [post()];
    reject(
        &output(&resources, false),
        &resources,
        true,
        "缺少唯一聚合资产",
    );
    reject(
        &output(&resources, true),
        &resources,
        false,
        "聚合资产未获请求",
    );
}

#[test]
fn rejects_catalog_wrong_path_or_duplicate() {
    let mut value = output(&[], true);
    for path in [
        "src/generated/resources/other.ts",
        "/src/generated/resources/index.ts",
    ] {
        value["assets"][0]["path"] = json!(path);
        reject(&value, &[], true, "聚合资产未获请求或路径不正确");
    }
    let mut value = output(&[], true);
    value["assets"]
        .as_array_mut()
        .unwrap()
        .push(catalog_asset());
    reject(&value, &[], true, "路径重复");
}

#[test]
fn rejects_unknown_resources_and_wrong_roots() {
    let resources = [post()];
    let mut value = output(&resources, false);
    value["assets"][0]["resource"] = json!("秘密占位");
    reject(&value, &resources, false, "未知资源");
    for root in ["backend", "Frontend", "", "秘密占位"] {
        let mut value = output(&resources, false);
        value["assets"][0]["root"] = json!(root);
        reject(&value, &resources, false, "非 frontend 根资产");
    }
    let mut value = output(&[], true);
    value["assets"][0]["root"] = json!("backend");
    reject(&value, &[], true, "非 frontend 根资产");
}

#[test]
fn rejects_duplicate_resource_asset_paths() {
    let resources = [post()];
    let mut value = output(&resources, false);
    let duplicate = value["assets"][0].clone();
    value["assets"].as_array_mut().unwrap().push(duplicate);
    reject(&value, &resources, false, "路径重复");
}

#[test]
fn rejects_unsafe_or_out_of_scope_paths() {
    let resources = [post()];
    let invalid = [
        "",
        "/api.ts",
        "//api.ts",
        "../api.ts",
        "./api.ts",
        "a/../api.ts",
        "a/./api.ts",
        "a//api.ts",
        "a/",
        "a\\api.ts",
        "C:/api.ts",
        "A.ts",
        "a.TS",
        "a..ts",
        "a b.ts",
        "a%2fts.ts",
        "a:stream.ts",
        "é.ts",
        "api.js",
        "nested/page.vue",
        "other.vue",
        ".ts",
        "_a.ts",
        "-a.ts",
        "a\0.ts",
        "a\n.ts",
        "a\r.ts",
        "a/.hidden.ts",
    ];
    for relative in invalid {
        let mut value = output(&resources, false);
        value["assets"][0]["path"] = json!(format!("src/generated/resources/post/{relative}"));
        reject(&value, &resources, false, "路径不安全");
    }
    for path in [
        "/src/generated/resources/post/api.ts",
        "D:/src/generated/resources/post/api.ts",
        "src/generated/resources/other/api.ts",
        "src/generated/resources/postfix/api.ts",
        "src/generated/resources/index.ts",
        "src/generated/resources/post",
        "src\\generated\\resources\\post\\api.ts",
        "crates/api.ts",
    ] {
        let mut value = output(&resources, false);
        value["assets"][0]["path"] = json!(path);
        reject(&value, &resources, false, "路径不安全");
    }
}

#[test]
fn rejects_unsafe_or_duplicate_ir_names() {
    for name in [
        "",
        "Post",
        "../post",
        "post/item",
        "post\\item",
        "post-name",
        "2post",
        "_post",
        "é",
        "__catalog__",
    ] {
        let mut resource = post();
        resource.name = name.into();
        reject(&output(&[], false), &[resource], false, "IR 名称不是安全");
    }
    reject(&output(&[], false), &[post(), post()], false, "IR 名称重复");
}

#[test]
fn rejects_wrong_versions_and_version_types() {
    for version in [
        json!(0),
        json!(2),
        json!(-1),
        json!(1.5),
        json!("1"),
        Value::Null,
        json!(true),
    ] {
        let mut value = output(&[], false);
        value["format_version"] = version;
        reject(&value, &[], false, "协议");
    }
    for version in [json!("秘密占位"), json!(""), json!(1), Value::Null] {
        let mut value = output(&[], false);
        value["generator_version"] = version;
        reject(&value, &[], false, "协议");
    }
}

#[test]
fn rejects_unknown_missing_or_wrongly_typed_envelope_fields() {
    let mut value = output(&[], false);
    value["秘密占位"] = json!("秘密占位");
    reject(&value, &[], false, "严格 JSON");
    for field in ["format_version", "generator_version", "assets"] {
        let mut value = output(&[], false);
        value.as_object_mut().unwrap().remove(field);
        reject(&value, &[], false, "严格 JSON");
    }
    for assets in [Value::Null, json!({}), json!("秘密占位"), json!([null])] {
        let mut value = output(&[], false);
        value["assets"] = assets;
        reject(&value, &[], false, "严格 JSON");
    }
    for value in [Value::Null, json!([]), json!(1), json!("秘密占位")] {
        reject(&value, &[], false, "严格 JSON");
    }
}

#[test]
fn rejects_unknown_missing_or_wrongly_typed_asset_fields() {
    let resources = [post()];
    let mut value = output(&resources, false);
    value["assets"][0]["秘密占位"] = json!("秘密占位");
    reject(&value, &resources, false, "严格 JSON");
    for field in ["resource", "root", "path", "content"] {
        let mut value = output(&resources, false);
        value["assets"][0].as_object_mut().unwrap().remove(field);
        reject(&value, &resources, false, "严格 JSON");
        for invalid in [Value::Null, json!(1), json!([]), json!({})] {
            let mut value = output(&resources, false);
            value["assets"][0][field] = invalid;
            reject(&value, &resources, false, "严格 JSON");
        }
    }
}

#[test]
fn rejects_positional_arrays_instead_of_protocol_objects() {
    reject(
        &json!([1, crate::GENERATOR_VERSION, []]),
        &[],
        false,
        "严格 JSON",
    );
    let asset = catalog_asset();
    let mut value = output(&[], true);
    value["assets"][0] = json!([
        asset["resource"],
        asset["root"],
        asset["path"],
        asset["content"],
    ]);
    reject(&value, &[], true, "严格 JSON");
}

#[test]
fn rejects_duplicate_json_fields_at_both_levels() {
    let base = output(&[], false);
    let source = serde_json::to_string(&base).unwrap();
    for field in ["format_version", "generator_version", "assets"] {
        let duplicate = format!("{{\"{field}\":{},{}", base[field], &source[1..]);
        reject_bytes(duplicate.as_bytes(), &[], false, "严格 JSON");
    }
    let asset = catalog_asset();
    let asset_source = serde_json::to_string(&asset).unwrap();
    for field in ["resource", "root", "path", "content"] {
        let duplicate = format!("{{\"{field}\":{},{}", asset[field], &asset_source[1..]);
        let source = format!(
            "{{\"format_version\":1,\"generator_version\":{},\"assets\":[{duplicate}]}}",
            base["generator_version"],
        );
        reject_bytes(source.as_bytes(), &[], true, "严格 JSON");
    }
}

#[test]
fn rejects_invalid_utf8_invalid_json_and_trailing_values() {
    reject_bytes(&[0xff, 0xfe], &[], false, "有效 UTF-8");
    for source in ["", "{", "{\"秘密占位\":", "{}{}", "null null"] {
        reject_bytes(source.as_bytes(), &[], false, "严格 JSON");
    }
    let valid = serde_json::to_string(&output(&[], false)).unwrap();
    for suffix in ["{}", " null", " 秘密占位"] {
        reject_bytes(
            format!("{valid}{suffix}").as_bytes(),
            &[],
            false,
            "严格 JSON",
        );
    }
    let source = format!(" \n\t{valid}\n\t ");
    assert!(
        decode_assets(source.as_bytes(), &[], false)
            .unwrap()
            .is_empty()
    );
}

#[test]
fn rejects_outputs_over_64_mib_before_parsing() {
    reject_bytes(&vec![b' '; 64 * 1024 * 1024 + 1], &[], false, "超过 64 MiB");
}

#[test]
fn accepts_output_at_the_exact_byte_limit() {
    let mut source = serde_json::to_vec(&output(&[], false)).unwrap();
    source.resize(64 * 1024 * 1024, b' ');
    assert!(decode_assets(&source, &[], false).unwrap().is_empty());
}

#[test]
fn rejects_inexact_resource_and_catalog_headers_without_leaking_content() {
    let resources = [post()];
    for index in [0, 1] {
        let original = output(&resources, false);
        let content = original["assets"][index]["content"].as_str().unwrap();
        for invalid in [
            "// 秘密占位\n".into(),
            format!("// 秘密占位\n{content}"),
            content.replacen(crate::GENERATOR_VERSION, "秘密占位", 1),
            content.replacen("resource: post", "resource: 秘密占位", 1),
            content.replacen(&resources[0].source_path, "秘密占位", 1),
            content.replace("请勿手工修改", "秘密占位"),
        ] {
            let mut value = original.clone();
            value["assets"][index]["content"] = json!(invalid);
            reject(&value, &resources, false, "缺少精确");
        }
    }
    let original = output(&[], true);
    let content = original["assets"][0]["content"].as_str().unwrap();
    for invalid in [
        comment_content(&resources[0], false),
        content.replacen(crate::GENERATOR_VERSION, "秘密占位", 1),
        format!("// 秘密占位\n{content}"),
        content.replace("请勿手工修改", "秘密占位"),
    ] {
        let mut value = original.clone();
        value["assets"][0]["content"] = json!(invalid);
        reject(&value, &[], true, "缺少精确");
    }
    let mut value = output(&resources, false);
    value["assets"][0]["content"] = catalog_asset()["content"].clone();
    reject(&value, &resources, false, "缺少精确");
}

#[test]
fn rejects_cr_anywhere_in_resource_or_catalog_content() {
    let resources = [post()];
    for index in [0, 1, 5] {
        let mut value = output(&resources, true);
        let content = value["assets"][index]["content"].as_str().unwrap();
        value["assets"][index]["content"] = json!(format!("{content}\r秘密占位"));
        reject(&value, &resources, true, "包含 CR");
    }
}

#[test]
fn enforces_ts_vue_and_catalog_line_limits_with_or_without_final_lf() {
    let resources = [post()];
    for (index, limit) in [(0, 300), (1, 600), (5, 300)] {
        for final_lf in [false, true] {
            for extra in [0, 1] {
                let mut value = output(&resources, true);
                let mut content = value["assets"][index]["content"]
                    .as_str()
                    .unwrap()
                    .to_owned();
                let comment = if index == 1 {
                    "<!-- 占位 -->\n"
                } else {
                    "// 占位\n"
                };
                content.push_str(&comment.repeat(limit + extra - content.lines().count()));
                if !final_lf {
                    content.pop();
                }
                value["assets"][index]["content"] = json!(content);
                if extra == 0 {
                    assert_eq!(decode(&value, &resources, true).len(), 6);
                } else {
                    reject(&value, &resources, true, &format!("超过 {limit} 行"));
                }
            }
        }
    }
}
